<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Revisión de arqueo</title><style>body{font-family:system-ui,sans-serif;background:#f4f7fb;color:#183453;margin:0;padding:28px}.wrap{max-width:980px;margin:auto;background:white;border-radius:14px;padding:26px;box-shadow:0 4px 20px #15335312}table{width:100%;border-collapse:collapse}td,th{padding:10px;text-align:left;border-bottom:1px solid #e3eaf3}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px}.tile{background:#edf4fc;border-radius:10px;padding:14px}.alert{background:#fff0e7;padding:12px;border-radius:8px}button{background:#165ba5;color:white;border:0;border-radius:8px;padding:12px 18px;cursor:pointer}a{color:#165ba5}</style></head><body><main class="wrap"><p><a href="{{ route($rutaBase.'.certificaciones.index') }}">← Volver a certificaciones</a></p><h1>Arqueo {{ $arqueo->numero_arqueo }}</h1>@if(session('success'))<p>{{ session('success') }}</p>@endif@if($errors->any())<div class="alert">{{ $errors->first() }}</div>@endif<p><strong>Agencia:</strong> {{ $arqueo->agencia_nombre_historico }} · <strong>Ventanilla:</strong> {{ $arqueo->ventanilla_codigo_historico }}</p><p><strong>Receptor:</strong> {{ $arqueo->receptor_nombre_historico }} · <strong>Fecha:</strong> {{ $arqueo->fecha_operativa?->format('d/m/Y') }} · <strong>Estado:</strong> {{ $arqueo->estado }}</p><div class="grid"><div class="tile">Billetes<br><strong>Q {{ number_format((float)$arqueo->total_billetes,2) }}</strong></div><div class="tile">Monedas<br><strong>Q {{ number_format((float)$arqueo->total_monedas,2) }}</strong></div><div class="tile">Total arqueado<br><strong>Q {{ number_format((float)$arqueo->total_arqueado,2) }}</strong></div><div class="tile">Corte<br><strong>Q {{ number_format((float)$arqueo->total_corte,2) }}</strong></div><div class="tile">Diferencia<br><strong>Q {{ number_format((float)$arqueo->diferencia,2) }}</strong></div></div><h2>Desglose</h2><table><thead><tr><th>Tipo</th><th>Denominación</th><th>Cantidad</th><th>Subtotal</th></tr></thead><tbody>@foreach($arqueo->detalles as $detalle)<tr><td>{{ $detalle->tipo }}</td><td>{{ $detalle->denominacion ?? $detalle->concepto }}</td><td>{{ $detalle->cantidad }}</td><td>Q {{ number_format((float)$detalle->subtotal,2) }}</td></tr>@endforeach</tbody></table><p><strong>Justificación de diferencia:</strong> {{ $arqueo->justificacion_diferencia ?: 'Sin diferencia justificada' }}</p><p><strong>Observaciones:</strong> {{ $arqueo->observaciones ?: 'Ninguna' }}</p><p><strong>Firma receptor:</strong> {{ $firmaReceptorValida ? 'Íntegra y verificada' : 'NO VÁLIDA' }}</p>@if($arqueo->estado==='CERTIFICADO')<p><strong>Firma certificador:</strong> {{ $firmaCertificadorValida ? 'Íntegra y verificada' : 'NO VÁLIDA' }}</p><p><strong>Certificado el:</strong> {{ $arqueo->certificado_at?->format('d/m/Y H:i:s') }}</p>@elseif($arqueo->estado==='PENDIENTE' && $firmaReceptorValida)<form method="POST" action="{{ route($rutaBase.'.certificaciones.store',$arqueo->id) }}">@csrf<label><input type="checkbox" name="confirmar_certificacion" value="1" required> He revisado los valores y confirmo la certificación electrónica de este arqueo.</label><p><button type="submit">Firmar y certificar arqueo</button></p></form>@else<p class="alert">Este arqueo no está disponible para certificación o la firma del receptor no es válida.</p>@endif</main></body></html>